function verificarResposta(e,a,t){document.getElementById(e).dataset.jaRespondeu;var o=document.querySelector("#"+e+' input[type="radio"]:checked'),n=document.querySelector("#"+e+" .retorno"),r=n.querySelector(".explicacao");n.style.display="block";var s=o.value;if(s===a){var c=o.parentNode.dataset.comentario;r.innerHTML="<span class='bold'>Comentário:</span> <br><br>"+c,n.style.display="block",o.parentNode.classList.add("opcao-correta")}else{var d=document.getElementById(e);if(d.classList.add("shake-animation"),document.body.classList.add("shake-animation-active"),setTimeout(function(){document.body.classList.remove("shake-animation-active")},1e3),t){document.querySelector("#"+e+' input[value="'+a+'"]').parentNode.dataset.comentario;r.innerHTML="<span class='bold'>A resposta correta é a alternativa "+a.toUpperCase()+":</span> <br><br><span class='bold'>Comentário:</span> "}var l=o.parentNode.dataset.comentario;r.innerHTML+="<br><br>"+l,n.style.display="block",o.parentNode.classList.add("opcao-incorreta")}document.getElementById(e).dataset.jaRespondeu="true",document.querySelectorAll("#"+e+' input[type="radio"]').forEach(function(e){e.disabled=!0}),document.querySelectorAll("#"+e+" .opcoes label").forEach(function(e){e.style.pointerEvents="none",e.style.cursor="default"})}